function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

function spinWheel(opts){
  opts=opts||{}; var seed=opts.seed!=null?opts.seed:1; var r=rngFactory(seed);
  var lines=String(opts.items||'').split(/\n/).map(function(s){return String(s).trim();}).filter(Boolean);
  if(!lines.length) return {ok:false, reason:'请至少输入一个选项'};
  var names=[], weights=[];
  for(var i=0;i<lines.length;i++){
    var p=lines[i].split(/\s*[:：]\s*/);
    var w=p.length>1 ? Number(p[p.length-1]) : 1;
    if(!isFinite(w) || w<0) w=1;
    names.push(p.length>1 ? p.slice(0,-1).join(' ').trim() : lines[i]);
    weights.push(w);
  }
  var total=0;
  for(var j=0;j<weights.length;j++) total+=weights[j];
  if(!(total>0)){ for(var q=0;q<weights.length;q++) weights[q]=1; total=weights.length; }
  var x=r()*total, acc=0, idx=weights.length-1;
  for(var k=0;k<weights.length;k++){ acc+=weights[k]; if(x<=acc){ idx=k; break; } }
  return {ok:true, winner:names[idx], index:idx, names:names, weights:weights, total:total, options:names.length};
}

var EXPORTS={spinWheel:spinWheel};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpinWheelForgePure = EXPORTS; }
